document.querySelectorAll('[data-lab="CP00-I1"]').forEach(root=>{const z=root.dataset.lang==='zh',tau=root.querySelector('[data-field="tau"]'),obs=root.querySelector('[data-field="obs"]'),a=root.querySelector('[data-field="a"]'),out=root.querySelector('[data-field="out"]');const X=q=>80+585*q,Y=s=>340-295*s/10;function update(){const tr=10**(+tau.value),to=10**(+obs.value),aa=+a.value,de=tr/to,S=t=>10*(aa+(1-aa)*Math.exp(-t/tr));let lab='';[0,.25,.5,.75,1].forEach(q=>lab+=`<text x="${X(q)}" y="371" text-anchor="middle">${Number((to*q).toPrecision(3))}</text>`);[0,2,4,6,8,10].forEach(s=>lab+=`<text x="66" y="${Y(s)+6}" text-anchor="end">${s}</text>`);root.querySelector('[data-field="ticks"]').innerHTML=lab;const samples=[0];for(let i=0;i<=160;i++)samples.push(to*10**(-5+5*i/160));const path=samples.map((t,i)=>`${i?'L':'M'}${X(t/to)} ${Y(S(t))}`).join(' ');root.querySelector('[data-field="curve"]').setAttribute('d',path);root.querySelector('[data-field="floor"]').setAttribute('d',`M80 ${Y(10*aa)}H665`);const d=root.querySelector('[data-field="dot"]');d.setAttribute('cx',665);d.setAttribute('cy',Y(S(to)));out.textContent=z?`τr=${tr.toFixed(2)} s，观察${to.toFixed(2)} s，De=${de.toFixed(3)}。窗口结束时应力${S(to).toFixed(3)} kPa，保留初始值的${(10*S(to)).toFixed(2)}%；长期平台${(10*aa).toFixed(1)} kPa。可松弛部分剩余${(100*Math.exp(-to/tr)).toFixed(2)}%。`:`τr = ${tr.toFixed(2)} s; observation ${to.toFixed(2)} s; De = ${de.toFixed(3)}. End-of-window stress ${S(to).toFixed(3)} kPa, or ${(10*S(to)).toFixed(2)}% of its initial value; long-time plateau ${(10*aa).toFixed(1)} kPa. The relaxing contribution retains ${(100*Math.exp(-to/tr)).toFixed(2)}%.`;}[tau,obs,a].forEach(el=>el.addEventListener('input',update));a.addEventListener('change',update);update();});